    });

    // Edge Case: Error during fetch
    it('renders error message when fetch fails', async () => {
        const mockFetchData = jest.fn().mockRejectedValue(new Error('Fetch failed'));
        render(<DataFetcher fetchData={mockFetchData} />);

        expect(screen.getByText(/loading/i)).toBeInTheDocument();

        await waitFor(() => expect(screen.queryByText(/loading/i)).not.toBeInTheDocument());
        expect(screen.getByText(/error/i)).toBeInTheDocument();
        expect(screen.getByText(/fetch failed/i)).toBeInTheDocument();
    });

    // Edge Case: Handle no data returned
    it('renders nothing when fetch returns null', async () => {
        const mockFetchData = jest.fn().mockResolvedValue(null);
        render(<DataFetcher fetchData={mockFetchData} />);

        expect(screen.getByText(/loading/i)).toBeInTheDocument();

        await waitFor(() => expect(screen.queryByText(/loading/i)).not.toBeInTheDocument());
        expect(screen.queryByText(/data:/i)).not.toBeInTheDocument();
        expect(screen.queryByText(/error/i)).not.toBeInTheDocument();
    });
});
